"""扫描 Rust 源码里的 axum 路由，生成 Markdown 接口文档（路径、方法、参数、返回）。
"""
use std::collections::HashMap;

struct Scanner {
    source: String,
}

impl Scanner {
    fn new(source: String) -> Self {
        Scanner { source }
    }

    fn scan() -> HashMap<String, Vec<(String, String)>> {
        let mut result = HashMap::new();
        for line in source.lines().filter(|l| l.contains("axum")) {
            if let Some(rest) = line.split_whitespace().skip(1).take_while(|&s| s != "}").next() {
                result.insert(rest.to_string(), vec![(String::from("GET"), String::from("path")), (String::from("param1"), String::from("type"))]);
            }
        }
        result
    }
}

import os
from typing import List, Tuple

class Router:
    def __init__(self):
        self.routes: List[Tuple[str, str]] = []

    def add_route(self, path: str, method: str) -> None:
        """Add a route."""
        self.routes.append((path, method))

    def match(self, path: str, method: str) -> Tuple[str, str]:
        """Match a request to a route."""
        for route_path, route_method in self.routes:
            if route_method == method and path.startswith(route_path):
                return (route_path, route_method)
        raise ValueError("No matching route")


if __name__ == "__main__":
