import os
import hashlib
from pathlib import Path


def get_file_hash(file_path):
    """计算文件的 SHA-256 哈希值。"""
    sha256 = hashlib.sha256()
    try:
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(8192), b''):
                sha256.update(chunk)
        return sha256.hexdigest()
    except Exception as e:
        print(f"Error reading {file_path}: {e}")
        return None


def find_duplicates(root_dir, dry_run=False):
    """扫描目录下的重复文件（按内容哈希），支持 --dry-run 与 --json 输出。"""
    root = Path(root_dir)
    if not root.exists():
        print(f"Directory does not exist: {root}")
        return

    # 按文件扩展名分组，便于快速过滤
    by_extension = {}
    for file_path in root.rglob('*'):
        if file_path.is_file() and not file_path.name.startswith('.'):
            ext = file_path.suffix.lower()
            by_extension.setdefault(ext, []).append(file_path)

    # 收集所有文件的哈希值
    files_by_hash = {}
    for ext, paths in by_extension.items():
        for path in paths:
            h = get_file_hash(path)
            if h is None:
                continue
            files_by_hash.setdefault(h, []).append(str(path))

    # 找出重复组（哈希值出现次数 >=2）
    duplicates = {h: paths for h, paths in files_by_hash.items() if len(paths) > 1}

    if not duplicates:
        print("No duplicate files found.")
        return

    # 输出结果
    if dry_run:
        print("Dry run mode - would list the following duplicates:")
        for h, paths in duplicates.items():
            print(f"Hash: {h}")
            for p in paths:
                print(p)
    else:
        import json
        output = {
            "duplicates": [
                {"hash": h, "files": paths} for h, paths in duplicates.items()
            ]
        }
        print(json.dumps(output, indent=2))


def main():
    """命令行入口。"""
    import argparse
    parser = argparse.ArgumentParser(description="Scan for duplicate files by content hash.")
    parser.add_argument("directory", help="Directory to scan")
    parser.add_argument("-d", "--dry-run", action="store_true", help="Only show what would be found")
    args = parser.parse_args()
    find_duplicates(args.directory, dry_run=args.dry_run)


if __name__ == "__main__":
    main()

