"""实现一个线程安全的缓存系统，支持并发读写、过期时间控制与数据完整性校验。"""
import threading
from datetime import datetime, timedelta

class CacheEntry:
    """单个缓存条目，包含 key、value、创建时间、过期时间。"""
    def __init__(self, key, value):
        self.key = key
        self.value = value
        self.create_time = datetime.now()
        self.expires_at = None  # 将在 set 时赋值

class SecureCache:
    """线程安全的缓存系统。"""
    def __init__(self, ttl: int = 300):
        self.ttl = timedelta(seconds=ttl)
        self._cache = {}
        self._lock = threading.Lock()

    def set(self, key, value):
        """设置缓存条目，key 为 str，value 为任意可序列化对象。"""
        with self._lock:
            entry = CacheEntry(key, value)
            entry.expires_at = datetime.now() + self.ttl
            self._cache[key] = entry

    def get(self, key):
        """获取缓存条目，若不存在或已过期则返回 None。"""
        with self._lock:
            entry = self._cache.get(key)
            if entry is None or datetime.now() > entry.expires_at:
                return None
            return entry.value

    def delete(self, key):
        """删除指定键的缓存条目。"""
        with self._lock:
            self._cache.pop(key, None)

if __name__ == "__main__":
    cache = SecureCache(ttl=2)  # 2秒过期
    cache.set("a", {"data": 1})
    print(cache.get("a"))  # {'data': 1}
    import time; time.sleep(3)
    print(cache.get("a"))  # None

"""把多行 JSON 日志按小时聚合成统计表，输出 CSV。"""
import json
from datetime import datetime, timedelta

def parse_json_logs(file_path):
    """读取并解析 JSON 日志文件。"""
    logs = []
    with open(file_path, 'r', encoding='utf-8') as f:
        for line in f:
            if line.strip():
                try:
                    log_entry = json.loads(line)
                    logs.append(log_entry)
                except json.JSONDecodeError:
                    continue
    return logs

def group_by_hour(logs):
    """按小时聚合日志。"""
    groups = {}
    for log in logs:
        timestamp = log.get('timestamp')
        if not isinstance(timestamp, str):
            continue
        try:
            dt = datetime.fromisoformat(timestamp.replace('Z', '+00:00'))
        except ValueError:
            continue
        hour_key = dt.strftime('%Y-%m-%d %H')
        if hour_key not in groups:
            groups[hour_key] = {'count': 0, 'total_duration': 0}
        groups[hour_key]['count'] += 1
    return groups

def write_csv(groups, output_path):
    """将分组结果写入 CSV。"""
    with open(output_path, 'w', encoding='utf-8') as f:
        writer = csv.writer(f)
        writer.writerow(['hour', 'count', 'total_duration'])
        for hour_key in sorted(groups.keys()):
            data = groups[hour_key]
            writer.writerow([hour_key, data['count'], data['total_duration']])

if __name__ == '__main__':
    import sys
    input_file = sys.argv[1] if len(sys.argv) > 1 else 'logs.json'
    output_file = 'stats.csv'
    logs = parse_json_logs(input_file)
    groups = group_by_hour(logs)
    write_csv(groups, output_file)

"""日志聚合器：读取多文件日志，按时间范围过滤并输出汇总报告。"""
import os
from datetime import datetime, timezone

# 定义日志行结构：每行格式为 "timestamp|level|message"，timestamp 为 ISO8601 字符串。
LOG_ROW = "{ts}|{lvl}|{msg}"

class LogAggregator:
    def __init__(self, start_time: str, end_time: str):
        self.start_time = datetime.fromisoformat(start_time).replace(tzinfo=timezone.utc)
        self.end_time = datetime.fromisoformat(end_time).replace(tzinfo=timezone.utc)

    def parse_line(self, line: str) -> tuple:
        """解析单行日志，返回 (timestamp, level, message)。"""
        if not line or line.strip() == "":
            return None
        parts = line.split("|")
        if len(parts) != 3:
            return None
        ts_str, lvl, msg = parts[0], parts[1], parts[2]
        try:
            timestamp = datetime.fromisoformat(ts_str).replace(tzinfo=timezone.utc)
        except ValueError:
            return None
        if not (self.start_time <= timestamp <= self.end_time):
            return None
        return (timestamp, lvl, msg)

    def aggregate(self, lines: list) -> dict:
        """按级别聚合日志行，返回 {level: [lines]}。"""
        result = {}
        for line in lines:
            parsed = self.parse_line(line)
            if parsed is None:
                continue
            ts, lvl, msg = parsed
            if lvl not in result:
                result[lvl] = []
            result[lvl].append((ts, msg))
        return result


def main():
    start_time = "2023-01-01T00:00:00+00:00"
    end_time = "2023-12-31T23:59:59+00:00"
    aggregator = LogAggregator(start_time, end_time)

    # 读取所有 .log 文件
    log_files = [f for f in os.listdir(".") if f.endswith(".log")]
    all_lines = []
    for file_path in log_files:
        with open(file_path, "r", encoding="utf-8") as f:
            all_lines.extend(f.readlines())

    aggregated = aggregator.aggregate(all_lines)

    # 输出汇总报告
    print("日志聚合报告：")
    for level in sorted(aggregated.keys()):
        lines = aggregated[level]
        print(f"\n级别: {level}")
        for ts, msg in lines:
            print(f"  - {ts}: {msg}")


if __name__ == "__main__":
    main()

"""扫描目录下的重复文件（按内容哈希），支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import os
import sys

def compute_hash(filepath):
    """计算文件的 SHA256 哈希值。"""
    h = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()


def find_duplicates(directory):
    """查找目录下相同内容的文件。返回 (dict, list) 的元组。"""
    hash_map = {}
    for root, _, files in os.walk(directory):
        for file in files:
            path = os.path.join(root, file)
            if not os.path.isfile(path):
                continue
            h = compute_hash(path)
            hash_map.setdefault(h, []).append(path)
    return hash_map, []


def main():
    parser = argparse.ArgumentParser(description='扫描目录下的重复文件（按内容哈希）。')
    parser.add_argument('directory', help='要扫描的目录路径。')
    parser.add_argument('--dry-run', action='store_true', help='仅打印将要删除的文件，不实际操作。')
    parser.add_argument('--json', action='store_true', help='以 JSON 格式输出结果。')

    args = parser.parse_args()
    hash_map, dupes = find_duplicates(args.directory)

    if not args.json:
        for h, paths in hash_map.items():
