                print(f'哈希值 {h} 的重复文件：')
                for p in paths:
                    print(p)
    else:
        result = {
            'duplicates': []
        }
        for h, paths in hash_map.items():
            if len(paths) > 1:
                result['duplicates'].append({'hash': h, 'files': paths})
