import os
from typing import List, Tuple

# 哈希分组优化器：先按文件大小分桶，再对同尺寸文件算哈希，避免大文件全量扫描。
class HashOptimizer:
    def __init__(self):
        self._buckets: dict[str, list] = {}

    def _bucket_key(self, size_mb: float) -> str:
        """按 MB 整数分桶，相同尺寸归一组。"""
        return f"{int(size_mb // 1)}"

    def _hash(self, path: str) -> str:
        """计算文件哈希（SHA-256），返回十六进制字符串。"""
        import hashlib
        h = hashlib.sha256()
        with open(path, 'rb') as f:
            for chunk in iter(lambda: f.read(8192), b''):
                h.update(chunk)
        return h.hexdigest()

    def optimize(self, paths: List[str]) -> dict:
        """返回 {尺寸分组: [哈希列表]}，大文件先不扫描。"""
        buckets = {}
        for path in paths:
            try:
                size_mb = os.path.getsize(path) / (1024 * 1024)
            except OSError:
                continue
            key = self._bucket_key(size_mb)
            if key not in buckets:
                buckets[key] = []
            buckets[key].append(self._hash(path))
        return buckets


def main():
    paths = sys.argv[1:]
    opt = HashOptimizer()
    result = opt.optimize(paths)
    for size, hashes in sorted(result.items()):
        print(f"{size}MB: {len(hashes)} files")

if __name__ == "__main__":
    import sys
    main()

"""数据清洗工具：读取 CSV、处理缺失值与重复行、输出规范 CSV。"""
import csv
from datetime import datetime

def load_csv(file_path):
    """读取 CSV，返回列表（每行是字符串列表）。"""
    rows = []
    with open(file_path, 'r', encoding='utf-8') as f:
        reader = csv.reader(f)
        for row in reader:
            rows.append(row)
    return rows


def clean_rows(rows):
    """删除完全重复的行。"""
    seen = set()
    cleaned = []
    for row in rows:
        key = tuple(row)
        if key not in seen:
            seen.add(key)
            cleaned.append(row)
    return cleaned


def fix_date(date_str):
    """尝试将日期字符串转为 datetime。"""
    try:
        return datetime.strptime(date_str, '%Y-%m-%d')
    except ValueError:
        return None


def write_csv(file_path, rows):
    """写入 CSV，处理缺失值（留空）。"""
    with open(file_path, 'w', encoding='utf-8', newline='') as f:
        writer = csv.writer(f)
        for row in rows:
            cleaned_row = []
            for cell in row:
                if cell is None or cell == '':
                    continue
                try:
                    dt = fix_date(cell)
                    if dt:
                        cleaned_row.append(dt.strftime('%Y-%m-%d'))
                    else:
                        cleaned_row.append(cell)
                except ValueError:
                    cleaned_row.append(cell)
            writer.writerow(cleaned_row)


def main():
    """主流程：读入 → 去重 → 输出。"""
    input_path = 'input.csv'
    output_path = 'output.csv'
    rows = load_csv(input_path)
    cleaned_rows = clean_rows(rows)
    write_csv(output_path, cleaned_rows)


if __name__ == '__main__':
    main()

